package dev.david.tessel.core.sim

import dev.david.tessel.core.content.*
import dev.david.tessel.core.net.*

/** Targeted deterministic checks use fixtures, not the campaign bot harness. */
fun main(){
    var passed=0
    fun test(name:String,block:()->Unit){block();passed++;println("PASS $name")}
    fun world(stage:Int=1)=World(23).apply { spawning=false; if(stage>1)skipTo(stage) }
    fun choose(w:World,frame:TankEvolution){w.shop.open(w);val at=(0 until TankEvolution.REWARD_SLOTS).first{TankEvolution.fromReward(w.shop.rewardOffer(0,it))==frame};check(w.shop.pickPerk(w,0,at))}
    test("catalog 33 stable frames, four first branches") {check(TankEvolution.entries.size==33);check(TankEvolution.options(TankEvolution.BASIC,5).size==4);check(TankEvolution.entries.drop(1).all{it.parent in 0 until it.ordinal});check(TankEvolution.entries.all{it.barrels<=10})}
    test("three paid slots; retired generic multishot and velocity excluded") {val w=world();w.players.coins[0]=100000;w.shop.open(w);repeat(100){for(i in 0 until SHOP_SLOTS){check(w.shop.item(0,i) !in listOf(Upgrades.MULTISHOT,Upgrades.VELOCITY))};w.shop.reroll(w,0)};check(SHOP_SLOTS==3)}
    test("evolution route and incompatible spend refund") {val w=world(5);w.players.levels[0][Upgrades.MULTISHOT]=3;w.players.upgradeSpent[0][Upgrades.MULTISHOT]=100;choose(w,TankEvolution.TWIN);check(w.players.volley(0)==2);check(w.players.coins[0]==70);check(w.players.levels[0][Upgrades.MULTISHOT]==0);w.skipTo(15);choose(w,TankEvolution.TRIPLET);w.skipTo(25);choose(w,TankEvolution.FOCUS);check(w.players.volley(0)==3)}
    test("secret path unlocks only at stage 40") {val w=world(5);w.shop.open(w);val at=(0 until TankEvolution.REWARD_SLOTS).first{w.shop.rewardOffer(0,it)==TankEvolution.STAY_BASIC};check(w.shop.pickPerk(w,0,at));check(w.players.evolution[0]==TankEvolution.BASIC);w.skipTo(40);w.shop.open(w);check((0 until TankEvolution.REWARD_SLOTS).mapNotNull{TankEvolution.fromReward(w.shop.rewardOffer(0,it))}.toSet()==setOf(TankEvolution.PRISM,TankEvolution.DREADNOUGHT,TankEvolution.TEMPEST));choose(w,TankEvolution.PRISM);check(w.players.pierce(0)>=48)}
    test("overlord path to eight emitter mothership") {val w=world(5);choose(w,TankEvolution.SNIPER);w.skipTo(15);choose(w,TankEvolution.OVERSEER);w.skipTo(25);choose(w,TankEvolution.OVERLORD);w.skipTo(35);choose(w,TankEvolution.MOTHERSHIP);check(w.players.volley(0)==8);check(w.players.evolution[0].drones)}
    test("checkpoint evolution and spend roundtrip") {val w=world(5);choose(w,TankEvolution.RAMMER);w.players.upgradeSpent[0][Upgrades.DAMAGE]=121;val cp=Checkpoint.read(w.capture().write())!!;check(cp.evolution[0]==TankEvolution.RAMMER);check(cp.upgradeSpent[0][Upgrades.DAMAGE]==121);check(cp.lastEvolutionStage[0]==5)}
    test("Rammer shield prevents contact damage; consumes cooldown") {val w=world(5);choose(w,TankEvolution.RAMMER);val hp=w.players.hp[0];w.hurtPlayer(0,Cause.touch(Bestiary.DOT));check(w.players.hp[0]==hp);check(w.players.shieldCooldown[0]>0);w.hurtPlayer(0,Cause.shot(Bestiary.DOT));check(w.players.hp[0]<hp)}
    test("poison three ticks, stage-scaled hit") {val w=world(21);val hp=w.players.hp[0];w.hurtPlayer(0,Cause.shot(Bestiary.VENOM));check(w.players.hp[0]==hp-2);val input=Array(MAX_PLAYERS){PlayerInput()};repeat(3*TICK_HZ){w.step(input)};check(w.players.hp[0]==hp-5);check(w.players.poisonTicks[0]==0)}
    test("freeze applies bounded stun") {val w=world(26);w.hurtPlayer(0,Cause.shot(Bestiary.FROST));check(w.players.stun[0] in 1..30)}
    test("late enemies fit existing packed type field") {check(Bestiary.size==32);check(Bestiary.of(Bestiary.EMBER).trailEvery>0);check(Bestiary.of(Bestiary.VENOM).status==StatusEffect.POISON);check(Bestiary.of(Bestiary.FROST).status==StatusEffect.FREEZE)}
    test("twin bosses both required") {val w=world(30);val input=Array(MAX_PLAYERS){PlayerInput()};repeat(95){w.step(input)};val ids=(0 until w.enemies.count).filter{Bestiary.of(w.enemies.type[it]).boss};check(ids.size==2);for(j in ids)w.enemies.mode[j]=1;w.damageEnemy(ids[0],1e8f,1f,0f,0);check(w.phase==Phase.FIGHT);w.damageEnemy(ids[1],1e8f,1f,0f,0);check(w.phase==Phase.CLEAR)}
    test("core shield and replenishment; tracking trail bounded; hidden reinforcement phase") {val w=world(50);val i=w.spawnEnemy(Bestiary.CORE,500f,400f);w.enemies.mode[i]=1;w.core.begin();w.core.think(i,1f);val h=w.core.hazards;check(h.shield>0f);val initial=h.shield;check(h.absorb(initial*.5f)==0f);check(h.shield<initial);repeat(4*TICK_HZ){h.tick(i,1)};check(h.shield>initial*.5f);repeat(2*TICK_HZ){h.tick(i,1)};check(h.count in 1..CoreHazards.CAP);w.enemies.hp[i]=w.enemies.maxHp[i]*.45f;h.tick(i,1);check(h.hidden>0);check(h.absorb(1e6f)==0f);check(w.enemies.count>1)}
    test("status and core snapshot roundtrip") {val w=world(50);val i=w.spawnEnemy(Bestiary.CORE,500f,400f);w.enemies.mode[i]=1;w.core.begin();w.core.think(i,1f);w.players.poisonTicks[0]=120;val h=w.core.hazards;repeat(6*TICK_HZ){h.tick(i,1)};val buf=Wire.buffer(MAX_MESSAGE*2);Protocol.writeSnapshot(buf,w,false,false,0,Events(),Events(),Events(),0,Echo());val s=Snapshot();Protocol.readSnapshot(Wire.open(Wire.finish(buf)),s);check(s.poisonTicks[0]==120);check(s.beamCount==h.count);check(kotlin.math.abs(s.coreShield-h.shieldShare)<.01f)}
    test("remote hurt IDs preserve unsigned and contact sentinel") {val reports=Reports();reports.hurt(65535);reports.hurt(-12345);val buf=Wire.buffer(1024);Protocol.writeInput(buf,PlayerInput(),20f,20f,reports,Echo());val out=Reports();Protocol.readInput(Wire.open(Wire.finish(buf)),PlayerInput(),out,Echo());check(out.hurtBy[0]==65535&&out.hurtBy[1]==-12345)}
    test("stage repair only once and boss hull growth") {val w=world();w.players.hp[0]=4;val input=Array(MAX_PLAYERS){PlayerInput()};repeat(STAGE_TICKS+1){w.step(input)};check(w.phase==Phase.SHOP);check(w.players.hp[0]==5);val hp=w.players.hp[0];val cp=Checkpoint.read(w.capture().write())!!;w.restore(cp,27){true};check(w.players.hp[0]==hp);check(CampaignScaling.hullGrowth(5)==2&&CampaignScaling.hullGrowth(6)==0)}
    println("$passed/15 evolution/hazard checks passed")
}
